import random

def partition(l, lo, hi):
    pivot = l[hi]
    i = lo - 1
    for j in range(lo, hi):
        if l[j] <= pivot:
            i += 1
            l[i], l[j] = l[j], l[i]
    l[i+1], l[hi] = l[hi], l[i+1]
    return i + 1

def quickselect(l, lo, hi, k):
    if lo == hi:
        return l[lo]
    pivot_idx = partition(l, lo, hi)
    if pivot_idx == k - 1:
        return l[k - 1]
    elif pivot_idx < k - 1:
        return quickselect(l, pivot_idx + 1, hi, k)
    else:
        return quickselect(l, lo, pivot_idx - 1, k)

def median(l):
    n = len(l)
    if n % 2 == 0:
        return (quickselect(l, n // 2 - 1, n // 2, 2) + quickselect(l, n // 2, n // 2 + 1, 2)) / 2
    else:
        return quickselect(l, n // 2, n // 2 + 1, 1)
```

